let items = [];
let nextId = 1;
function add(text) { const it = { id: nextId++, text, done: false }; items.push(it); return it; }
function list() { return items.slice(); }
function reset() { items = []; nextId = 1; }
function remove(id) { const n = items.length; items = items.filter((i) => i.id !== id); return items.length < n; }
function complete(id) { const it = items.find((i) => i.id === id); if (!it) return null; it.done = true; return it; }
module.exports = { add, list, reset, remove, complete };

